#!/usr/bin/env bash
# Script to run benchmarking for all extrinsics of all peaq pallets
# Places autogenerated weights files in runtime/common/src/weights folder
#
# DESCRIPTION:
#   This script benchmarks all peaq pallets (both local and external) and generates
#   weight files for each pallet. It automatically discovers local pallets in the
#   pallets/ directory and includes external peaq pallets from git dependencies.
#
#   Local Pallets (from pallets/ directory):
#     - address-unification
#     - block-reward
#     - inflation-manager
#     - parachain-staking
#     - xc-asset-config
#
#   External Pallets (from external repositories):
#     - Transaction (peaq-pallet-transaction)
#     - PeaqDid (peaq-pallet-did)
#     - PeaqRbac (peaq-pallet-rbac)
#     - PeaqStorage (peaq-pallet-storage)
#     - PeaqMor (peaq-pallet-mor)
#
#   The script uses the following benchmark command format:
#     ./target/release/peaq-node benchmark pallet \
#       --chain=<chain> \
#       --execution=native \
#       --wasm-execution=compiled \
#       --pallet=<pallet_name> \
#       --extrinsic="*" \
#       --steps=<steps> \
#       --repeat=<repeat> \
#       --output=<output_file>
#
# FEATURES:
#   - Automatically builds the binary if it doesn't exist (with runtime-benchmarks feature)
#   - Verifies binary supports benchmarking before running
#   - Colored output for better readability
#   - Progress tracking and summary report
#   - Error handling with detailed failure reporting
#
# USAGE:
#   ./scripts/benchmark_peaq_pallets.sh [chain] [binary_path] [steps] [repeat]
#
# ARGUMENTS:
#   chain       - Chain name to benchmark (default: peaq-local)
#                 Common options: peaq-local, peaq, dev-local, krest, krest-local
#   binary_path - Path to peaq-node binary (default: ./target/release/peaq-node)
#                 The script will attempt to build it if it doesn't exist
#   steps       - Number of steps for benchmarking (default: 50)
#                 Higher values provide more accurate results but take longer
#   repeat      - Number of repeats for benchmarking (default: 20)
#                 Higher values provide more accurate results but take longer
#
# OUTPUT:
#   All generated weight files are placed in: ./runtime/common/src/weights/
#   Each pallet generates a file named after its crate (e.g., peaq_pallet_did.rs)
#
# EXAMPLES:
#   # Run with all defaults (peaq-local chain, 50 steps, 20 repeats)
#   ./scripts/benchmark_peaq_pallets.sh
#
#   # Run with custom chain
#   ./scripts/benchmark_peaq_pallets.sh dev-local
#
#   # Run with custom chain and binary path
#   ./scripts/benchmark_peaq_pallets.sh peaq-local ./target/release/peaq-node
#
#   # Run with custom steps and repeats for more accurate results
#   ./scripts/benchmark_peaq_pallets.sh peaq-local ./target/release/peaq-node 100 50
#
#   # Run for production chain with high accuracy
#   ./scripts/benchmark_peaq_pallets.sh peaq ./target/release/peaq-node 200 100
#
#   # Run with debug binary (if you have one built)
#   ./scripts/benchmark_peaq_pallets.sh dev-local ./target/debug/peaq-node 10 5
#
# EXIT CODES:
#   0 - All pallets benchmarked successfully
#   1 - One or more pallets failed to benchmark
#
# REQUIREMENTS:
#   - Rust toolchain with cargo
#   - peaq-node binary with runtime-benchmarks feature (will be built automatically)
#   - Valid chain specification that exists in the node

set -e

# Default values
CHAIN="${1:-peaq-local}"
BINARY_PATH="${2:-./target/release/peaq-node}"
STEPS="${3:-50}"
REPEAT="${4:-20}"

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# Function to print colored output
print_info() {
    echo -e "${BLUE}[INFO]${NC} $1"
}

print_success() {
    echo -e "${GREEN}[SUCCESS]${NC} $1"
}

print_warning() {
    echo -e "${YELLOW}[WARNING]${NC} $1"
}

print_error() {
    echo -e "${RED}[ERROR]${NC} $1"
}

# Check if binary exists
if [ ! -f "$BINARY_PATH" ]; then
    print_error "Binary not found at $BINARY_PATH"
    print_info "Building node with runtime-benchmarks feature..."
    cargo build --release --features runtime-benchmarks --bin peaq-node
    if [ ! -f "$BINARY_PATH" ]; then
        print_error "Failed to build binary. Please build manually with:"
        print_info "cargo build --release --features runtime-benchmarks --bin peaq-node"
        exit 1
    fi
    print_success "Binary built successfully"
fi

# Verify binary has benchmarking feature
print_info "Verifying benchmarking feature..."
if ! "$BINARY_PATH" benchmark --help &>/dev/null; then
    print_error "Binary does not support benchmarking. Please rebuild with --features runtime-benchmarks"
    exit 1
fi

# Create output directory
WEIGHTS_DIR="./runtime/common/src/weights"
mkdir -p "$WEIGHTS_DIR"
print_info "Weights output directory: $WEIGHTS_DIR"

# Function to get pallet mapping for a directory name
# Returns "pallet_name:output_filename" or empty string if not found
get_pallet_mapping() {
    local dir_name="$1"
    case "$dir_name" in
        "address-unification")
            echo "address_unification:address_unification"
            ;;
        "block-reward")
            echo "pallet_block_reward:pallet_block_reward"
            ;;
        "inflation-manager")
            echo "inflation_manager:inflation_manager"
            ;;
        "parachain-staking")
            echo "parachain-staking:parachain_staking"
            ;;
        "xc-asset-config")
            echo "xc_asset_config:xc_asset_config"
            ;;
        *)
            echo ""
            ;;
    esac
}

# External peaq pallets (not in local pallets/ directory)
# Format: "runtime_pallet_name:benchmark_pallet_name:output_filename"
EXTERNAL_PALLETS=(
    "Transaction:Transaction:peaq_pallet_transaction"
    "PeaqDid:PeaqDid:peaq_pallet_did"
    "PeaqRbac:PeaqRbac:peaq_pallet_rbac"
    "PeaqStorage:PeaqStorage:peaq_pallet_storage"
    "PeaqMor:PeaqMor:peaq_pallet_mor"
)

# Find all pallet directories
PALLET_DIRS=()
for dir in pallets/*/; do
    dir_name=$(basename "$dir")
    if [ -d "$dir" ] && [ -f "$dir/Cargo.toml" ]; then
        mapping=$(get_pallet_mapping "$dir_name")
        if [ -n "$mapping" ]; then
            PALLET_DIRS+=("$dir_name")
        fi
    fi
done

TOTAL_PALLETS=$((${#PALLET_DIRS[@]} + ${#EXTERNAL_PALLETS[@]}))

if [ $TOTAL_PALLETS -eq 0 ]; then
    print_error "No peaq pallets found to benchmark"
    exit 1
fi

print_info "Found ${#PALLET_DIRS[@]} local pallet(s) and ${#EXTERNAL_PALLETS[@]} external pallet(s) to benchmark (total: $TOTAL_PALLETS)"
print_info "Starting benchmarking for chain: $CHAIN"
print_info "Steps: $STEPS, Repeat: $REPEAT"
echo ""

# Track results
SUCCESS_COUNT=0
FAILED_COUNT=0
FAILED_PALLETS=()

# Benchmark local pallets (from pallets/ directory)
for PALLET_DIR in "${PALLET_DIRS[@]}"; do
    # Get pallet name and output filename from mapping function
    mapping=$(get_pallet_mapping "$PALLET_DIR")
    IFS=':' read -r PALLET_NAME OUTPUT_NAME <<< "$mapping"
    
    print_info "Benchmarking local pallet: $PALLET_DIR (--pallet=$PALLET_NAME)"
    
    # Output file path in runtime/common
    WEIGHT_FILE="$WEIGHTS_DIR/${OUTPUT_NAME}.rs"
    
    # Build benchmark command matching the format from weights.rs comments
    BENCHMARK_CMD=(
        "$BINARY_PATH"
        benchmark
        pallet
        --chain="$CHAIN"
        --execution=native
        --wasm-execution=compiled
        --pallet="$PALLET_NAME"
        --extrinsic="*"
        --steps="$STEPS"
        --repeat="$REPEAT"
        --output="$WEIGHT_FILE"
    )
    
    # Run benchmark
    if "${BENCHMARK_CMD[@]}"; then
        if [ -f "$WEIGHT_FILE" ]; then
            print_success "Completed benchmarking for $PALLET_DIR"
            print_info "  Weight file: $WEIGHT_FILE"
            ((SUCCESS_COUNT++))
        else
            print_warning "Benchmark completed for $PALLET_DIR but weight file not found at $WEIGHT_FILE"
            ((FAILED_COUNT++))
            FAILED_PALLETS+=("$PALLET_DIR")
        fi
    else
        print_error "Failed to benchmark $PALLET_DIR"
        ((FAILED_COUNT++))
        FAILED_PALLETS+=("$PALLET_DIR")
    fi
    echo ""
done

# Benchmark external peaq pallets (from external repositories)
for PALLET_ENTRY in "${EXTERNAL_PALLETS[@]}"; do
    # Parse entry: "runtime_pallet_name:benchmark_pallet_name:output_filename"
    IFS=':' read -r RUNTIME_NAME PALLET_NAME OUTPUT_NAME <<< "$PALLET_ENTRY"
    
    print_info "Benchmarking external pallet: $RUNTIME_NAME (--pallet=$PALLET_NAME)"
    
    # Output file path in runtime/common
    WEIGHT_FILE="$WEIGHTS_DIR/${OUTPUT_NAME}.rs"
    
    # Build benchmark command matching the format from weights.rs comments
    BENCHMARK_CMD=(
        "$BINARY_PATH"
        benchmark
        pallet
        --chain="$CHAIN"
        --execution=native
        --wasm-execution=compiled
        --pallet="$PALLET_NAME"
        --extrinsic="*"
        --steps="$STEPS"
        --repeat="$REPEAT"
        --output="$WEIGHT_FILE"
    )
    
    # Run benchmark
    if "${BENCHMARK_CMD[@]}"; then
        if [ -f "$WEIGHT_FILE" ]; then
            print_success "Completed benchmarking for $RUNTIME_NAME"
            print_info "  Weight file: $WEIGHT_FILE"
            ((SUCCESS_COUNT++))
        else
            print_warning "Benchmark completed for $RUNTIME_NAME but weight file not found at $WEIGHT_FILE"
            ((FAILED_COUNT++))
            FAILED_PALLETS+=("$RUNTIME_NAME")
        fi
    else
        print_error "Failed to benchmark $RUNTIME_NAME"
        ((FAILED_COUNT++))
        FAILED_PALLETS+=("$RUNTIME_NAME")
    fi
    echo ""
done

# Print summary
echo "=========================================="
print_info "Benchmarking Summary"
echo "=========================================="
print_success "Successful: $SUCCESS_COUNT pallet(s)"
if [ $FAILED_COUNT -gt 0 ]; then
    print_error "Failed: $FAILED_COUNT pallet(s)"
    print_warning "Failed pallets: ${FAILED_PALLETS[*]}"
fi
echo ""
print_info "Generated weight files in: $WEIGHTS_DIR"
if [ -d "$WEIGHTS_DIR" ]; then
    ls -lh "$WEIGHTS_DIR"/*.rs 2>/dev/null || print_warning "No weight files generated"
fi
echo ""

if [ $FAILED_COUNT -eq 0 ]; then
    print_success "All pallets benchmarked successfully!"
    exit 0
else
    print_error "Some pallets failed to benchmark"
    exit 1
fi
